CREATE TABLE key_versions(id uuid PRIMARY KEY,class text NOT NULL,version bigint NOT NULL,wrapped bytea NOT NULL,active boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(class,version));
CREATE UNIQUE INDEX key_versions_active ON key_versions(class) WHERE active;
CREATE TABLE storage_providers(id uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('local','s3')),config jsonb NOT NULL,priority int NOT NULL DEFAULT 0,enabled boolean NOT NULL DEFAULT true,draining boolean NOT NULL DEFAULT false);
ALTER TABLE files ADD COLUMN provider_id uuid REFERENCES storage_providers(id);
ALTER TABLE files ADD COLUMN upload_offset bigint NOT NULL DEFAULT 0;
ALTER TABLE files ADD COLUMN upload_epoch bigint NOT NULL DEFAULT 0;
ALTER TABLE files ADD COLUMN write_lease_until timestamptz;
ALTER TABLE files ADD COLUMN salt bytea;
ALTER TABLE files ADD COLUMN key_id uuid REFERENCES key_versions(id);
ALTER TABLE files ADD COLUMN crc32 bigint;
ALTER TABLE files ADD COLUMN content_type text;
ALTER TABLE files ADD COLUMN frozen boolean NOT NULL DEFAULT false;
ALTER TABLE transfers ADD COLUMN title text NOT NULL DEFAULT '';
ALTER TABLE transfers ADD COLUMN message text NOT NULL DEFAULT '';
ALTER TABLE transfers ADD COLUMN frozen boolean NOT NULL DEFAULT false;
ALTER TABLE transfers ADD COLUMN remaining_ttl_seconds double precision;
ALTER TABLE transfers ADD COLUMN access_epoch bigint NOT NULL DEFAULT 1;
CREATE INDEX files_provider ON files(provider_id);
CREATE INDEX files_key ON files(key_id);
CREATE TABLE file_chunks(id uuid PRIMARY KEY,file_id uuid NOT NULL REFERENCES files(id),chunk_index bigint NOT NULL,plain_offset bigint NOT NULL,plain_length int NOT NULL CHECK(plain_length>=0 AND plain_length<=4194304),object_key text NOT NULL UNIQUE,plain_sha256 text NOT NULL,UNIQUE(file_id,chunk_index),UNIQUE(file_id,plain_offset));
CREATE INDEX file_chunks_file ON file_chunks(file_id,plain_offset);
CREATE TABLE deletion_jobs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,provider_id uuid NOT NULL REFERENCES storage_providers(id),object_key text NOT NULL UNIQUE,file_id uuid REFERENCES files(id),attempts int NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT clock_timestamp(),lease_epoch bigint NOT NULL DEFAULT 0,lease_until timestamptz,completed_at timestamptz);
CREATE INDEX deletion_jobs_pending ON deletion_jobs(available_at) WHERE completed_at IS NULL;
CREATE INDEX deletion_jobs_provider ON deletion_jobs(provider_id);
CREATE INDEX deletion_jobs_file ON deletion_jobs(file_id);
CREATE TABLE recipient_links(id uuid PRIMARY KEY,transfer_id uuid NOT NULL REFERENCES transfers(id),recipient_email text,token_hash text NOT NULL UNIQUE,token_envelope bytea NOT NULL,password_hash text,epoch bigint NOT NULL DEFAULT 1,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX recipient_links_transfer ON recipient_links(transfer_id);
CREATE TABLE recipient_sessions(id uuid PRIMARY KEY,link_id uuid NOT NULL REFERENCES recipient_links(id),token_hash text NOT NULL UNIQUE,link_epoch bigint NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX recipient_sessions_link ON recipient_sessions(link_id);
CREATE TABLE recipient_file_refs(session_id uuid NOT NULL REFERENCES recipient_sessions(id),file_id uuid NOT NULL REFERENCES files(id),ref_hash text NOT NULL UNIQUE,PRIMARY KEY(session_id,file_id));
CREATE INDEX recipient_refs_file ON recipient_file_refs(file_id);
CREATE TABLE downloads(id uuid PRIMARY KEY,recipient_session_id uuid NOT NULL REFERENCES recipient_sessions(id),transfer_id uuid NOT NULL REFERENCES transfers(id),transfer_epoch bigint NOT NULL,kind text NOT NULL CHECK(kind IN ('file','zip')),state text NOT NULL DEFAULT 'leased',fence bigint NOT NULL DEFAULT 1,lease_until timestamptz NOT NULL,writer_until timestamptz,coverage jsonb NOT NULL DEFAULT '[]',total_size bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz);
CREATE INDEX downloads_session ON downloads(recipient_session_id);
CREATE INDEX downloads_transfer ON downloads(transfer_id);
CREATE TABLE download_files(download_id uuid NOT NULL REFERENCES downloads(id),file_id uuid NOT NULL REFERENCES files(id),PRIMARY KEY(download_id,file_id));
CREATE INDEX download_files_file ON download_files(file_id);
CREATE TABLE download_journal(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,transfer_id uuid NOT NULL REFERENCES transfers(id),download_id uuid NOT NULL UNIQUE REFERENCES downloads(id),occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),file_count int NOT NULL,total_bytes bigint NOT NULL,status text NOT NULL);
CREATE INDEX download_journal_transfer ON download_journal(transfer_id,id);
ALTER TABLE recipient_links ADD COLUMN key_id uuid NOT NULL REFERENCES key_versions(id);
CREATE INDEX recipient_links_key ON recipient_links(key_id);
